        'disable-ethernet' => ['Ethernet disabled', 'Disabled Ethernet adapter %s.'],
        'enable-wifi'      => ['WiFi enabled',      'Enabled WiFi adapter %s.'],
        'disable-wifi'     => ['WiFi disabled',     'Disabled WiFi adapter %s.'],
    );
