sub read_text {
    my ($path) = @_;
    open my $handle, '<', $path or die "open $path: $!";
    local $/;
    my $text = <$handle>;
    close $handle or die "close $path: $!";
    return $text;
}

sub relative_path {
    my ($path) = @_;
