sub compile_perl {
    my ($path) = @_;
    my $error = gensym;
    my $pid = open3(undef, my $stdout, $error, $^X, '-c', $path);
    my $output = do { local $/; <$stdout> // q{} };
    my $diagnostic = do { local $/; <$error> // q{} };
    waitpid($pid, 0);
    my $status = $?;
    return ($status == 0, $output . $diagnostic);
}

