use LabwcNetworkControlAction::Command;
use LabwcNetworkControlAction::Validation;

has command => (
    is      => 'ro',
    default => sub {
        LabwcNetworkControlAction::Command->new(
            path => '/usr/sbin:/usr/bin:/sbin:/bin',
        );
    },
);

has sys_class_net => (
    is      => 'ro',
    isa     => Str,
