sub interface_name {
    my ($self, $interface) = @_;

    defined($interface) && $interface ne q{} && $interface =~ /\A[A-Za-z0-9_.:-]+\z/
        or die "invalid capture interface: " . (defined($interface) ? $interface : 'unset') . "\n";
